import { test, expect } from './fixtures';

test('generated /coupon smoke', async ({ page }) => {
  await page.goto('/#/coupon');
  await expect(page.getByTestId('coupon-title')).toBeVisible();
  await page.getByTestId('coupon-code').fill('test');
  await page.getByTestId('coupon-apply').click();
  await expect(page.getByTestId('coupon-msg')).toBeVisible();
});

